steps.css:
body {
  max-width: 430px;
  margin: 30px auto;
  padding: 24px;
  font-family: Arial, sans-serif;
  text-align: center;
  color: #25312f;
  background: #f8faf9;
}
h1 { letter-spacing: .05em; font-size: 1.65rem; }
.felder {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin: 20px 0;
}
.feld {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  border: 2px solid #c4ceca;
  background: white;
  font-size: 1.6rem;
  font-weight: bold;
  text-transform: uppercase;
}
.gruen { background: #568267; border-color: #568267; color: white; }
.gelb { background: #b3964e; border-color: #b3964e; color: white; }
.grau { background: #737d80; border-color: #737d80; color: white; }
input { padding: 10px; width: 190px; font-size: 1rem; border: 2px solid #c4ceca; border-radius: 5px; }
button { padding: 11px 14px; margin: 5px; color: white; background: #4e7164; border: 0; border-radius: 5px; cursor: pointer; }
button:hover { background: #36584b; }
p { min-height: 1.4em; }

